  "py": "import asyncio\nfrom dataclasses import dataclass, field\nfrom datetime import timedelta\n\nfrom temporalio import activity, workflow\nfrom temporalio.client import Client\nfrom temporalio.common import RetryPolicy\nfrom temporalio.exceptions import ActivityError, ApplicationError\nfrom temporalio.worker import Worker\n\nTASK_QUEUE = \"profiles\"\n\n\nclass NotFound(Exception):\n    pass\n\n\nclass TooManyRequests(Exception):\n    def __init__(self, retry_after: float) -> None:\n        self.retry_after = retry_after\n\n\nclass FakeApi:\n    \"\"\"Stand-in for a third-party API that tolerates only a few concurrent callers.\"\"\"\n\n    def __init__(self) -> None:\n        self.in_flight = 0\n        self.max_in_flight = 0\n        self.calls = 0\n        self.throttle_once: set[str] = set()\n        self.latency = 0.05\n\n    async def get_profile(self, user_id: str) -> str:\n        self.calls += 1\n        self.in_flight += 1\n        self.max_in_flight = max(self.max_in_flight, self.in_flight)\n        try:\n            await asyncio.sleep(self.latency)\n            if user_id.startswith(\"missing\"):\n                raise NotFound(user_id)\n            if user_id in self.throttle_once:\n                self.throttle_once.discard(user_id)\n                raise TooManyRequests(3)  # the API says: come back in 3 seconds\n            return f\"user {user_id}\"\n        finally:\n            self.in_flight -= 1\n\n\napi = FakeApi()\n\n\n@dataclass\nclass SyncResult:\n    profiles: dict[str, str] = field(default_factory=dict)\n    missing: list[str] = field(default_factory=list)\n    failed: list[str] = field(default_factory=list)\n\n\n@activity.defn\nasync def fetch_profile(user_id: str) -> str:\n    try:\n        return await api.get_profile(user_id)\n    except NotFound:\n        raise ApplicationError(f\"{user_id} does not exist\", type=\"NotFound\", non_retryable=True)\n    except TooManyRequests as e:\n        raise ApplicationError(\"429\", type=\"RateLimited\", next_retry_delay=timedelta(seconds=e.retry_after))\n\n\n@workflow.defn\nclass ProfileSyncWorkflow:\n    @workflow.run\n    async def run(self, user_ids: list[str]) -> SyncResult:\n        results = await asyncio.gather(\n            *[\n                workflow.execute_activity(\n                    fetch_profile,\n                    uid,\n                    start_to_close_timeout=timedelta(seconds=10),\n                    retry_policy=RetryPolicy(initial_interval=timedelta(seconds=1), maximum_attempts=5),\n                )\n                for uid in user_ids\n            ],\n            return_exceptions=True,  # one bad user must not lose the other results\n        )\n        out = SyncResult()\n        for uid, r in zip(user_ids, results):\n            if isinstance(r, ActivityError):\n                if isinstance(r.cause, ApplicationError) and r.cause.type == \"NotFound\":\n                    out.missing.append(uid)\n                else:\n                    out.failed.append(uid)\n            elif isinstance(r, BaseException):\n                raise r\n            else:\n                out.profiles[uid] = r\n        return out\n\n\ndef make_worker(client: Client, max_concurrent: int = 5, per_second: float | None = None) -> Worker:\n    \"\"\"The API only tolerates `max_concurrent` callers (and `per_second` calls); enforce that at the worker.\"\"\"\n    return Worker(\n        client,\n        task_queue=TASK_QUEUE,\n        workflows=[ProfileSyncWorkflow],\n        activities=[fetch_profile],\n        max_concurrent_activities=max_concurrent,  # at most N activities run at once on this worker\n        max_activities_per_second=per_second,  # and at most N start per second\n    )",
  "ts": "// ===== fanout.ts =====\nimport { ActivityFailure, ApplicationFailure, proxyActivities } from '@temporalio/workflow';\nimport type * as activities from './fanout.activities';\n\nexport const TASK_QUEUE = 'profiles';\n\nconst { fetchProfile } = proxyActivities<typeof activities>({\n  startToCloseTimeout: '10 seconds',\n  retry: { initialInterval: '1s', maximumAttempts: 5 },\n});\n\nexport interface SyncResult {\n  profiles: Record<string, string>;\n  missing: string[];\n  failed: string[];\n}\n\nexport async function profileSyncWorkflow(userIds: string[]): Promise<SyncResult> {\n  // allSettled: one bad user must not lose the other results\n  const results = await Promise.allSettled(userIds.map((id) => fetchProfile(id)));\n  const out: SyncResult = { profiles: {}, missing: [], failed: [] };\n  results.forEach((r, i) => {\n    const id = userIds[i];\n    if (r.status === 'fulfilled') out.profiles[id] = r.value;\n    else if (r.reason instanceof ActivityFailure && r.reason.cause instanceof ApplicationFailure && r.reason.cause.type === 'NotFound') out.missing.push(id);\n    else out.failed.push(id);\n  });\n  return out;\n}\n\n// ===== fanout.activities.ts =====\nimport { ApplicationFailure } from '@temporalio/activity';\n\nclass NotFound extends Error {}\nclass TooManyRequests extends Error {\n  constructor(readonly retryAfterSeconds: number) {\n    super('429');\n  }\n}\nconst sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));\n\n/** Stand-in for a third-party API that tolerates only a few concurrent callers. */\nclass FakeApi {\n  inFlight = 0;\n  maxInFlight = 0;\n  calls = 0;\n  throttleOnce = new Set<string>();\n  latencyMs = 50;\n\n  async getProfile(userId: string): Promise<string> {\n    this.calls++;\n    this.inFlight++;\n    this.maxInFlight = Math.max(this.maxInFlight, this.inFlight);\n    try {\n      await sleep(this.latencyMs);\n      if (userId.startsWith('missing')) throw new NotFound(userId);\n      if (this.throttleOnce.delete(userId)) throw new TooManyRequests(3); // the API says: come back in 3 seconds\n      return 'user ' + userId;\n    } finally {\n      this.inFlight--;\n    }\n  }\n}\nexport const api = new FakeApi();\n\nexport async function fetchProfile(userId: string): Promise<string> {\n  try {\n    return await api.getProfile(userId);\n  } catch (e) {\n    if (e instanceof NotFound) {\n      throw ApplicationFailure.create({ message: userId + ' does not exist', type: 'NotFound', nonRetryable: true });\n    }\n    if (e instanceof TooManyRequests) {\n      throw ApplicationFailure.create({ message: '429', type: 'RateLimited', nextRetryDelay: e.retryAfterSeconds * 1000 });\n    }\n    throw e;\n  }\n}\n\n// ===== fanout.worker.ts =====\nimport { NativeConnection, Worker } from '@temporalio/worker';\nimport * as activities from './fanout.activities';\nimport { TASK_QUEUE } from './fanout';\n\n/** The API only tolerates `maxConcurrent` callers (and `perSecond` calls); enforce that at the worker. */\nexport function makeWorker(connection: NativeConnection, opts: { maxConcurrent?: number; perSecond?: number } = {}) {\n  return Worker.create({\n    connection,\n    taskQueue: TASK_QUEUE,\n    workflowsPath: require.resolve('./fanout'),\n    activities,\n    maxConcurrentActivityTaskExecutions: opts.maxConcurrent ?? 5, // at most N activities run at once on this worker\n    maxActivitiesPerSecond: opts.perSecond, // and at most N start per second\n  });\n}"
